// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    BankActor a1;
    BankActor a2;

    function setUp() public {
        c = new ModifierEntrancy();
        a1 = new BankActor();
        a2 = new BankActor();
    }

    function testFuzz_property(uint256 choice) public {
        vm.assume(choice < 2);
        BankActor actor = choice == 0 ? a1 : a2;
        actor.doAirDrop(c);
        assertTrue(
            c.tokenBalance(address(actor)) == 20 && c.tokenBalance(address(1)) == 0,
            "successful airDrop credits caller, never address(1)"
        );
    }
}

contract BankActor {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function doAirDrop(ModifierEntrancy c) external {
        c.airDrop();
    }
}
